userscript.function:

sUtils.object.extend(true, $share, {
    config: {
        default: {
            page: {
                READY: false,
                PURPOSE: 'VIEW'
            }
        },
        ui: {
        }
    },
    apps: {},
    controller: {}
});

initDataStore();
initComponent();
initPage();


const store = $share.apps.dataStore = appDelegate.getDataStore()
if (store) {

    store.addPlugin('reducer', 'data.items', (storeApi) => {
        const state = storeApi.getState('data.items');
        const changed = storeApi.getChanged('data.items');

        const dispatch = [];
        for(let [i, row] of changed.entries()) {
            if(row['ACTION_TEXT'] === undefined) {
                dispatch.push(storeApi.action.updateRow({
                    path : 'data.items',
                    id : row[store.STR.ROW_ID],
                    data : {
                        ...row,
                        ACTION_TEXT : sUtils.cache.text.get(`POA_CONTRACT.AUDIT_TRAIL_ACTION_${row['ACTION']}`)
                    }
                }));
            }

        }

        return dispatch;
    });

} else {
    console.error('layout : DataStore is undefined');
}


const store = $share.apps.dataStore;

// 기본 뷰모드로 화면 로드, 페이지 준비상태로 상태변경
store.dispatch(store.action.update({
    path: 'page',
    data: {
        ...store.getState('page'),
        PURPOSE: $share.config.default.page.PURPOSE,
        READY: true
    }
}));

if (Sepoa.params?.isPopup) {
    // 화면 모드 설정
    if (Sepoa.params['PURPOSE']) {
        store.dispatch(store.action.update({
            path: 'page',
            data: {
                ...store.getState('page'),
                PURPOSE: Sepoa.params['PURPOSE']
            }
        }));
    }

    // 이력 조회 서비스 호출용 파라미터 세팅
    const params = {
        target: {
            name : 'sepoa.svc.contract.SepoaContractTemplateService',
            action : 'doSelectHistory'
        },
        data: {
            ...Sepoa.params
        }
    };

    // 조회 서비스 호출 및 콜백
    sUtils.connector.api('service', params).then(so => {
        if (so.flag) {
            const data = so.result[0];
            if (data) {
                store.dispatch(store.action.addRow({
                    path : 'data.items',
                    data : [
                        ...data
                    ]
                }));
            }
        } else {
            Alert(so.message);
        }
    });
}
